{"cards": [{"node_code": "N_0fd7f822162d3120", "definition": "研究三维空间刚性构件组成的连杆机构及并联机构的运动学特性、构型综合、自由度分析及工作空间映射。", "boundary": "聚焦于空间刚性机构的几何运动学，涵盖Stewart平台、球面/圆柱并联机构及空间开链/闭链机构的位姿解算与综合。侧重机构拓扑与运动传递规律，不涉及柔性元件变形、拓扑结构动态重构或具体动力学控制算法。", "includes": ["空间并联机构（如Stewart平台）的运动学建模与综合", "空间开链与闭链连杆机构的位姿分析与工作空间研究", "空间机构自由度计算与奇异性分析"], "excludes": ["柔性铰链或弹性元件的力学分析（归柔顺机构节点）", "机构拓扑结构的可重构变换原理（归变胞与折展机构节点）"], "sibling_distinctions": [{"other_code": "N_7124bb26e7f52f4f", "rule": "本节点处理刚性构件的空间运动；兄弟节点处理利用弹性变形实现运动的柔顺机构。"}, {"other_code": "N_0fa62929d2e012a6", "rule": "本节点侧重固定拓扑的空间运动学；兄弟节点侧重拓扑结构可变或可折展的机构原理。"}], "cross_boundary_rule": "涉及空间机构时，若侧重刚性构件运动学归本节点，若涉及柔性元件归柔顺机构，若涉及拓扑重构归变胞机构。"}, {"node_code": "N_7124bb26e7f52f4f", "definition": "研究利用构件弹性变形实现运动传递的柔顺机构及柔性铰链的构型设计、运动特性分析与综合方法。", "boundary": "聚焦于非刚性连接或整体弹性变形机构的运动学原理，涵盖柔性铰链、柔顺夹持器及微纳机构的构型综合。侧重机构构型与运动传递机制，不涉及柔性材料本构模型建立、疲劳寿命预测或具体微纳制造工艺。", "includes": ["柔性铰链（如十字、弓形）的构型设计与运动学分析", "柔顺机构（如柔顺夹持、柔顺传动）的原理与综合", "基于弹性变形的微纳机构运动特性研究"], "excludes": ["柔性材料的力学性能测试或本构模型建立（归材料或力学节点）", "微纳机构的制造工艺与设备（归制造工程节点）"], "sibling_distinctions": [{"other_code": "N_0fd7f822162d3120", "rule": "本节点核心在于弹性变形实现运动；兄弟节点核心在于刚性构件的空间几何运动。"}, {"other_code": "N_0fa62929d2e012a6", "rule": "本节点侧重弹性变形机制；兄弟节点侧重拓扑结构的可重构或折展变换。"}], "cross_boundary_rule": "涉及柔顺机构时，若侧重构型与运动学归本节点，若侧重材料力学分析归力学节点，若涉及拓扑重构归变胞机构。"}, {"node_code": "N_0fa62929d2e012a6", "definition": "研究拓扑结构可动态变换的变胞机构、可重构机构以及可折叠展开机构的运动原理、构型综合与变换规律。", "boundary": "聚焦于机构在运动过程中拓扑结构或几何形态发生显著变化的特性，涵盖变胞运动学、可重构机器人及空间折展结构。侧重结构变换原理与运动规律，不涉及具体工程应用系统的整体集成或控制策略。", "includes": ["变胞机构的运动学分析与拓扑变换原理", "可重构机构的构型综合与运动特性", "空间折展机构（如卫星天线）的展开运动学"], "excludes": ["固定拓扑空间机构的运动学（归空间连杆与并联机构节点）", "基于弹性变形的柔顺机构（归柔顺机构与柔性铰链节点）"], "sibling_distinctions": [{"other_code": "N_0fd7f822162d3120", "rule": "本节点侧重拓扑结构可变或可折展；兄弟节点侧重固定拓扑的空间运动学。"}, {"other_code": "N_7124bb26e7f52f4f", "rule": "本节点侧重结构形态/拓扑的宏观变换；兄弟节点侧重微观弹性变形实现运动。"}], "cross_boundary_rule": "涉及可重构机构时，若侧重拓扑变换原理归本节点，若侧重具体重构后的运动学归空间机构，若涉及柔性变形归柔顺机构。"}]}
